/* Cosmic Neon Orbit Background - MotionZync */
.cosmic-pulse-container {
    position: absolute;
    top: 0; 
    left: 0; 
    width: 100%; 
    height: 100%;
    overflow: hidden;
    z-index: 0; /* Live preview માટે */
    pointer-events: none;
    background-color: #050505;
}

.cosmic-orb {
    position: absolute;
    border-radius: 50%;
    filter: blur(90px);
    opacity: 0.5;
    animation: pulseFloat 10s infinite alternate ease-in-out;
    transition: transform 0.2s ease-out;
    mix-blend-mode: screen;
}

/* Purple Orb */
.orb-1 {
    width: 300px; 
    height: 300px;
    background: #7b2cbf;
    top: -10%; 
    left: -10%;
    transform: translate(calc(var(--mouse-x, 0.5) * 50px), calc(var(--mouse-y, 0.5) * 50px));
}

/* Cyan Orb */
.orb-2 {
    width: 250px; 
    height: 250px;
    background: #00ffcc;
    bottom: -10%; 
    right: -10%;
    animation-delay: -3s;
    transform: translate(calc(var(--mouse-x, 0.5) * -70px), calc(var(--mouse-y, 0.5) * -70px));
}

/* Pink Orb */
.orb-3 {
    width: 350px; 
    height: 350px;
    background: #ff0055;
    top: 30%; 
    left: 30%;
    animation-duration: 15s;
    opacity: 0.3;
    transform: translate(calc(var(--mouse-x, 0.5) * 30px), calc(var(--mouse-y, 0.5) * -30px));
}

@keyframes pulseFloat {
    0% { transform: scale(1) translate(0, 0); }
    50% { transform: scale(1.1) translate(20px, -20px); }
    100% { transform: scale(0.9) translate(-20px, 20px); }
}

