/* JS for Cosmic Neon Orbit */

// લાઈવ પ્રિવ્યુમાં ડુપ્લિકેટ ન થાય તે માટે જૂનું કન્ટેનર રિમૂવ કરો
const existingContainer = document.querySelector('.cosmic-pulse-container');
if (existingContainer) {
    existingContainer.remove();
}

// નવું કન્ટેનર બનાવો
const container = document.createElement('div');
container.className = 'cosmic-pulse-container';

// પ્રિવ્યુ વિન્ડોમાં એડ કરો (MotionZync Live Preview માટે)
document.body.appendChild(container);

// 3 ગ્લોઇંગ ઓર્બ્સ (Orbs) બનાવો
for(let i = 0; i < 3; i++) {
    const orb = document.createElement('div');
    orb.className = `cosmic-orb orb-${i+1}`;
    container.appendChild(orb);
}

// માઉસ મૂવમેન્ટ ઇન્ટરેક્શન (Mouse Interaction)
document.addEventListener('mousemove', (e) => {
    // વિન્ડોની સાઇઝ પ્રમાણે માઉસની પોઝિશન 0 થી 1 ની વચ્ચે સેટ કરો
    const x = e.clientX / window.innerWidth;
    const y = e.clientY / window.innerHeight;

    // CSS વેરીએબલ્સ અપડેટ કરો
    container.style.setProperty('--mouse-x', x);
    container.style.setProperty('--mouse-y', y);
});

