const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;justify-content:center;align-items:center;background:#0a0a0f;perspective:1000px;';

c.innerHTML = `
  <div class="sonic-ring" id="sRing">
    <div class="circle-layer c1"></div>
    <div class="circle-layer c2"></div>
    <div class="circle-layer c3"></div>
    <div class="core-text">ZYNK</div>
  </div>
`;

const sRing = document.getElementById('sRing');

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  const x = (e.clientX - rect.left - rect.width/2) * 0.15;
  const y = (e.clientY - rect.top - rect.height/2) * -0.15;

  // આખી સિસ્ટમને 3D માં ફેરવવા
  sRing.style.transform = `rotateX(${y}deg) rotateY(${x}deg)`;
});

c.addEventListener('pointerleave', () => {
  sRing.style.transform = `rotateX(0deg) rotateY(0deg)`;
});

const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:#111;position:relative;overflow:hidden;';

const vCvs = document.createElement('canvas');
const vCtx = vCvs.getContext('2d');
vCvs.width = window.innerWidth; vCvs.height = window.innerHeight;
c.appendChild(vCvs);

let voxels = [];
let vW = vCvs.width, vH = vCvs.height;
let mouse = { x: -1000, y: -1000 };

function initVoxels() {
  vCtx.fillStyle = 'white'; vCtx.font = '900 80px sans-serif';
  vCtx.textAlign = 'center'; vCtx.textBaseline = 'middle';
  vCtx.fillText('VOXEL', vW/2, vH/2);

  const data = vCtx.getImageData(0,0,vW,vH).data;
  vCtx.clearRect(0,0,vW,vH);

  voxels = [];
  for(let y=0; y<vH; y+=8){
    for(let x=0; x<vW; x+=8){
      if(data[(y*vW+x)*4+3] > 128) {
        voxels.push({
          baseX: x, baseY: y, x: x, y: y, z: 0,
          vx: 0, vy: 0, vz: 0, size: 6,
          color: `hsl(${300 + Math.random()*50}, 100%, 60%)` // પિંક અને પર્પલ
        });
      }
    }
  }
}
initVoxels(); window.addEventListener('resize', () => { vW = vCvs.width = window.innerWidth; vH = vCvs.height = window.innerHeight; initVoxels(); });

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  mouse.x = e.clientX - rect.left; mouse.y = e.clientY - rect.top;
});
c.addEventListener('pointerleave', () => { mouse.x = -1000; mouse.y = -1000; });

function drawVoxels() {
  vCtx.fillStyle = 'rgba(17, 17, 17, 0.4)'; vCtx.fillRect(0,0,vW,vH);

  // Z-index મુજબ સોર્ટિંગ (પાછળના ક્યુબ પેલા દોરાય)
  voxels.sort((a, b) => a.z - b.z);

  voxels.forEach(v => {
    let dx = mouse.x - v.x, dy = mouse.y - v.y;
    let dist = Math.sqrt(dx*dx + dy*dy);

    // જો કર્સર નજીક આવે તો 3D વિસ્ફોટ
    if(dist < 80) {
      let force = (80 - dist) / 80;
      v.vx -= (dx / dist) * force * 15;
      v.vy -= (dy / dist) * force * 15;
      v.vz += force * 20; // 3D માં આગળ આવવું
    }

    // મૂળ જગ્યાએ પાછા ફરવાનું ફિઝિક્સ (Spring physics)
    v.vx += (v.baseX - v.x) * 0.05;
    v.vy += (v.baseY - v.y) * 0.05;
    v.vz += (0 - v.z) * 0.05;

    // ઘર્ષણ (Friction)
    v.vx *= 0.8; v.vy *= 0.8; v.vz *= 0.8;

    v.x += v.vx; v.y += v.vy; v.z += v.vz;

    // 3D પ્રોજેક્શન (Projection Math)
    let perspective = 500 / (500 - v.z);
    let px = (v.x - vW/2) * perspective + vW/2;
    let py = (v.y - vH/2) * perspective + vH/2;
    let pSize = v.size * perspective;

    vCtx.fillStyle = v.color;
    vCtx.fillRect(px, py, pSize, pSize);
  });
  requestAnimationFrame(drawVoxels);
}
drawVoxels();

