const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;background:#010105;position:relative;overflow:hidden;';

c.innerHTML = `
  <canvas id="fluid-canvas"></canvas>
  <div class="fluid-text">FLUIDIC</div>
`;

const fCvs = document.getElementById('fluid-canvas');
const fCtx = fCvs.getContext('2d');
let fW = fCvs.width = window.innerWidth;
let fH = fCvs.height = window.innerHeight;

let points = [];
const maxPoints = 50;

c.addEventListener('pointermove', (e) => {
  const rect = c.getBoundingClientRect();
  points.push({
    x: e.clientX - rect.left,
    y: e.clientY - rect.top,
    life: 1.0
  });
});

function drawFluid() {
  fCtx.globalCompositeOperation = 'source-over';
  fCtx.fillStyle = 'rgba(1, 1, 5, 0.2)'; // સ્મૂધ ફેડિંગ ટ્રેલ
  fCtx.fillRect(0, 0, fW, fH);

  fCtx.globalCompositeOperation = 'lighter';

  if(points.length > 1) {
    fCtx.beginPath();
    for(let i = 0; i < points.length; i++) {
      let p = points[i];
      p.life -= 0.02; // ધીમે ધીમે ગાયબ થશે

      if(p.life <= 0) {
        points.splice(i, 1);
        i--; continue;
      }

      if(i === 0) fCtx.moveTo(p.x, p.y);
      else {
        // સ્મૂધ કર્વ (Smooth Curve) દોરવા માટે Quadratic Curve
        let prev = points[i - 1];
        let midX = (prev.x + p.x) / 2;
        let midY = (prev.y + p.y) / 2;
        fCtx.quadraticCurveTo(prev.x, prev.y, midX, midY);
      }
    }

    fCtx.strokeStyle = 'rgba(0, 255, 204, 0.8)';
    fCtx.lineWidth = 15;
    fCtx.lineCap = 'round';
    fCtx.lineJoin = 'round';
    fCtx.shadowBlur = 30;
    fCtx.shadowColor = '#00ffcc';
    fCtx.stroke();
  }

  requestAnimationFrame(drawFluid);
}
drawFluid();

