const fC = document.getElementById('container');
fC.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#111;';

fC.innerHTML = `
  <div class="fold-wrap">
    <div class="fold-sticky">
      <div class="fold-door fold-left" id="dLeft"></div>
      <div class="fold-door fold-right" id="dRight"></div>
      <div class="fold-content" id="dContent">ZYNK UNLOCKED</div>
      <div style="position:absolute; bottom:20px; color:#555; z-index:20;">SCROLL TO UNLOCK</div>
