const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#020510;position:relative;';

c.innerHTML = `
  <div class="globe-wrap">
    <canvas id="globe-canvas"></canvas>
    <div class="globe-text-layer">
      <div id="g1" class="globe-msg" style="font-size:20px; color:#aaa; top:20%;">CONNECTING WORLD ↓</div>
      <div id="g2" class="globe-msg">ZYNK NETWORK</div>
    </div>
  </div>
`;

const gCvs = document.getElementById('globe-canvas');
const gCtx = gCvs.getContext('2d');
let gW, gH;
let nodes = [];

function initGlobe() {
  gW = gCvs.width = window.innerWidth;
  gH = gCvs.height = window.innerHeight;
  nodes = [];
  // વાયરફ્રેમ ગ્લોબ (Sphere) માટે ૩D પોઈન્ટ્સ ગણવા
  for (let i = 0; i < 400; i++) {
    let theta = Math.random() * 2 * Math.PI;
    let phi = Math.acos(Math.random() * 2 - 1);
    let x = Math.sin(phi) * Math.cos(theta);
    let y = Math.sin(phi) * Math.sin(theta);
    let z = Math.cos(phi);
    nodes.push({x: x, y: y, z: z});
  }
}
initGlobe(); window.addEventListener('resize', initGlobe);

let gProg = 0;
c.addEventListener('scroll', () => {
  gProg = c.scrollTop / (c.scrollHeight - c.clientHeight);
  document.getElementById('g1').style.opacity = (gProg < 0.3) ? 1 : 0;

  const g2 = document.getElementById('g2');
  g2.style.opacity = (gProg > 0.6) ? 1 : 0;
  g2.style.transform = `scale(${1 + (gProg - 0.6)})`;
});

let rotation = 0;
function drawGlobe() {
  gCtx.clearRect(0,0,gW,gH);
  rotation += 0.005; // સતત ફરવા માટે

  // સ્ક્રોલ મુજબ ગ્લોબ ઝૂમ થશે
  let radius = Math.min(gW, gH) * 0.3 + (gProg * 200); 

  for (let i = 0; i < nodes.length; i++) {
    let p = nodes[i];

    // Y-Axis અને X-Axis પર 3D રોટેશન
    let rotX = p.x * Math.cos(rotation) - p.z * Math.sin(rotation);
    let rotZ = p.x * Math.sin(rotation) + p.z * Math.cos(rotation);

    // સ્ક્રોલ કરવાથી આખું ગ્લોબ ઊભું ફરશે
    let scrollRot = gProg * Math.PI;
    let finalY = p.y * Math.cos(scrollRot) - rotZ * Math.sin(scrollRot);

    let screenX = gW/2 + rotX * radius;
    let screenY = gH/2 + finalY * radius;

    gCtx.beginPath();
    gCtx.arc(screenX, screenY, 1.5, 0, Math.PI * 2);
    gCtx.fillStyle = '#00ffcc';
    gCtx.fill();
  }
  requestAnimationFrame(drawGlobe);
}
drawGlobe();

