const pCount = 1000; // મોબાઈલ માટે ઑપ્ટિમાઇઝ કરેલી સંખ્યા

function getPts(txt, size) {
  const tc = document.createElement('canvas');
  tc.width = W; tc.height = H;
  const tctx = tc.getContext('2d');
  tctx.fillStyle = 'white'; tctx.font = `900 ${size}px sans-serif`;
  tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
  tctx.fillText(txt, W/2, H/2 - 50); // લખાણ થોડું ઉપર રાખ્યું છે

  const data = tctx.getImageData(0, 0, W, H).data;
  let pts = [];
  for(let y=0; y<H; y+=6){
    for(let x=0; x<W; x+=6){
      if(data[(y * W + x) * 4 + 3] > 128) pts.push({x: x, y: y});
    }
  }
  return pts.length ? pts : [{x: W/2, y: H/2}];
}

function initZynk() {
  W = cvs.width = window.innerWidth;
  H = cvs.height = window.innerHeight;

  let s1 = getPts('ZYNK', Math.min(W/3, 100)); // Stage 1
  let s2 = []; // Stage 2: Orbit
  for(let i=0; i<pCount; i++) s2.push({x: Math.random() * W, y: Math.random() * H});

  let s3 = []; // Stage 3: Ocean Wave
  for(let i=0; i<pCount; i++){
    let nx = (i / pCount) * W;
    let ny = H/2 + Math.sin(nx * 0.04) * 50 + Math.cos(nx * 0.02) * 30;
    s3.push({x: nx, y: ny});
  }

  // Stage 4 માં પાર્ટીકલ્સ સ્ક્રીનની બહાર જતા રહેશે, કારણકે ગ્લોઇંગ કાર્ડ આવશે
  let s4 = [];
  for(let i=0; i<pCount; i++) s4.push({x: W/2 + (Math.random()-0.5)*3000, y: H/2 + (Math.random()-0.5)*3000});

  shapes = [s1, s2, s3, s4];

  particles = [];
  for(let i=0; i<pCount; i++){
    particles.push({x: W/2, y: H/2, c: `hsl(${180 + Math.random() * 80}, 100%, 60%)`}); // સાયન અને પર્પલ રંગો
  }
}
initZynk(); window.addEventListener('resize', initZynk);

let prog = 0;
mainWrap.addEventListener('scroll', () => {
  prog = mainWrap.scrollTop / (mainWrap.scrollHeight - mainWrap.clientHeight);

  document.getElementById('msg1').style.opacity = (prog < 0.1) ? 1 : 0;

  const m2 = document.getElementById('msg2');
  m2.style.opacity = (prog > 0.25 && prog < 0.45) ? 1 : 0;
  m2.style.transform = `scale(${1 + (prog - 0.25)})`;

  document.getElementById('msg3').style.opacity = (prog > 0.55 && prog < 0.75) ? 1 : 0;

  // અંતિમ કાર્ડ દેખાડવું
  if(prog > 0.85) document.getElementById('finalCard').classList.add('visible');
  else document.getElementById('finalCard').classList.remove('visible');
});

// મેગ્નેટિક બટન ઇફેક્ટ
const mBtn = document.getElementById('mBtn');
mBtn.addEventListener('pointermove', (e) => {
  const rect = mBtn.getBoundingClientRect();
  const x = (e.clientX - rect.left - rect.width/2) * 0.4;
  const y = (e.clientY - rect.top - rect.height/2) * 0.4;
  mBtn.style.transform = `translate(${x}px, ${y}px)`;
});
mBtn.addEventListener('pointerleave', () => mBtn.style.transform = `translate(0px, 0px)`);

function lerp(a, b, t){ return a + (b - a) * t; }

function drawZynk() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.3)'; // સ્મૂધ ટ્રેલ ઇફેક્ટ માટે
  ctx.fillRect(0, 0, W, H);

  let stage = prog * 3;
  let cS = Math.floor(stage);
  let nS = Math.min(cS + 1, 3);
  let t = stage - cS;

  let pts1 = shapes[cS], pts2 = shapes[nS];

  for(let i=0; i<pCount; i++){
    let p = particles[i];
    let t1 = pts1[i % pts1.length], t2 = pts2[i % pts2.length];

    let tx = lerp(t1.x, t2.x, t);
    let ty = lerp(t1.y, t2.y, t);

    if(cS === 1) { 
      tx += Math.sin(Date.now() * 0.001 + i) * 40;
      ty += Math.cos(Date.now() * 0.002 + i) * 40;
    }

    p.x += (tx - p.x) * 0.08; p.y += (ty - p.y) * 0.08;

    ctx.beginPath(); ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
    ctx.fillStyle = p.c; ctx.fill();
  }
  requestAnimationFrame(drawZynk);
}
drawZynk();

