const mainWrap = document.getElementById('container');
mainWrap.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#000;position:relative;';

mainWrap.innerHTML = `
  <div id="main-container">
    <canvas id="particle-canvas"></canvas>
    <div class="scroll-text-layer">
      <div id="msg1" class="scroll-msg">Scroll down to explode Logo</div>
      <div id="msg2" class="scroll-msg" style="font-size:40px; color:#00ffcc;">Particles are orbiting!</div>
      <div id="msg3" class="scroll-msg" style="font-size:40px; color:#ff007f;">Ocean Waves Forming...</div>
    </div>
  </div>
`;

const canvas = document.getElementById('particle-canvas');
const ctx = canvas.getContext('2d');
let W, H;
let particles = [];
let targetShapes = [];
const particleCount = 1500; // Mobile mate optimize karelu

// Text mathi points (x, y) shodhavani technique
function getTextPoints(text, fontSize) {
  const tmpCanvas = document.createElement('canvas');
  tmpCanvas.width = W; tmpCanvas.height = H;
  const tCtx = tmpCanvas.getContext('2d');
  tCtx.fillStyle = 'white';
  tCtx.font = `900 ${fontSize}px sans-serif`;
  tCtx.textAlign = 'center';
  tCtx.textBaseline = 'middle';
  tCtx.fillText(text, W/2, H/2);

  const imgData = tCtx.getImageData(0, 0, W, H).data;
  let points = [];
  // Gap 6px rakhi chhe jethi mobile hang na thay
  for(let y=0; y<H; y+=6){
    for(let x=0; x<W; x+=6){
      if(imgData[(y*W+x)*4+3] > 128) {
        points.push({x: x, y: y});
      }
    }
  }
  return points;
}

function initCanvas() {
  W = canvas.width = mainWrap.clientWidth || window.innerWidth;
  H = canvas.height = mainWrap.clientHeight || window.innerHeight;

  // 4 Stages na Shapes banavva
  let shape1 = getTextPoints('LOGO', Math.min(W/3, 120)); // Stage 1: LOGO

  let shape2 = []; // Stage 2: Random Orbiting (Chhuta padela)
  for(let i=0; i<particleCount; i++){
    shape2.push({ x: Math.random()*W, y: Math.random()*H });
  }

  let shape3 = []; // Stage 3: Samudra na Moja (Ocean Wave)
  for(let i=0; i<particleCount; i++){
    let nx = (i / particleCount) * W;
    let ny = H/2 + Math.sin(nx * 0.05) * 50 + Math.cos(nx * 0.02) * 30;
    shape3.push({ x: nx, y: ny });
  }

  let shape4 = getTextPoints('MOTIONZYNC', Math.min(W/5, 60)); // Stage 4: Web Name

  targetShapes = [shape1, shape2, shape3, shape4];

  // Particles ne initialize karva
  particles = [];
  for(let i=0; i<particleCount; i++){
    particles.push({
      x: W/2, y: H/2,
      color: `hsl(${Math.random()*60 + 180}, 100%, 70%)` // Cyan thi Blue shades
    });
  }
}

initCanvas();
window.addEventListener('resize', initCanvas);

let scrollProgress = 0;

mainWrap.addEventListener('scroll', () => {
  const maxScroll = mainWrap.scrollHeight - mainWrap.clientHeight;
  scrollProgress = mainWrap.scrollTop / maxScroll;

  // Text messages ne show/hide karva
  document.getElementById('msg1').style.opacity = (scrollProgress < 0.1) ? 1 : 0;
  document.getElementById('msg2').style.opacity = (scrollProgress > 0.3 && scrollProgress < 0.5) ? 1 : 0;
  document.getElementById('msg3').style.opacity = (scrollProgress > 0.6 && scrollProgress < 0.8) ? 1 : 0;
});

// Linear Interpolation (Lerp) - Be bindu vacche smooth movement mate
function lerp(start, end, amt) {
  return (1 - amt) * start + amt * end;
}

function animate() {
  ctx.clearRect(0, 0, W, H);

  // Scroll progress parthi nakki karvu ke kayo stage chhe (0, 1, 2, or 3)
  let stage = scrollProgress * 3; 
  let currentStage = Math.floor(stage);
  let nextStage = Math.min(currentStage + 1, 3);
  let stageProgress = stage - currentStage; // 0 to 1 vacche nu transition

  let pts1 = targetShapes[currentStage];
  let pts2 = targetShapes[nextStage];

  for(let i=0; i<particleCount; i++){
    let p = particles[i];

    // Arrays ma purepura points na hoy to repeat karva
    let t1 = pts1[i % pts1.length];
    let t2 = pts2[i % pts2.length];

    // Target X ane Y
    let targetX = lerp(t1.x, t2.x, stageProgress);
    let targetY = lerp(t1.y, t2.y, stageProgress);

    // Particles orbit karti vakhte thodo random wave effect aapvo
    if(currentStage === 1) {
       targetX += Math.sin(Date.now()*0.001 + i)*20;
       targetY += Math.cos(Date.now()*0.002 + i)*20;
    }

    // Smooth physics easing
    p.x += (targetX - p.x) * 0.1;
    p.y += (targetY - p.y) * 0.1;

    ctx.beginPath();
    ctx.arc(p.x, p.y, 2, 0, Math.PI*2);
    ctx.fillStyle = p.color;
    ctx.fill();
  }

  requestAnimationFrame(animate);
}
animate();

