const grid = document.createElement('div');
grid.className = 'anime-grid';

const boxes = [];
for (let r = 0; r < 10; r++) {
  for (let col = 0; col < 10; col++) {
    const box = document.createElement('div');
    box.className = 'anime-box';
    box.dataset.r = r; box.dataset.c = col;
    boxes.push(box);
    grid.appendChild(box);
  }
}
c.appendChild(grid);

grid.addEventListener('click', (e) => {
  if(!e.target.classList.contains('anime-box')) return;
  const targetR = parseInt(e.target.dataset.r);
  const targetC = parseInt(e.target.dataset.c);

  boxes.forEach(box => {
    const r = parseInt(box.dataset.r);
    const col = parseInt(box.dataset.c);
    const dist = Math.abs(r - targetR) + Math.abs(col - targetC);

    // Anime.js જેવું Staggered Delay
    setTimeout(() => {
      box.classList.add('active');
      setTimeout(() => box.classList.remove('active'), 400);
    }, dist * 50);
  });
});

