  { cls: 'bg-2', title: 'Technology' },
  { cls: 'bg-3', title: 'Animations' }
];

let currentIndex = 0;
const cardEls = [];

cardsData.forEach((data, i) => {
  const card = document.createElement('div');
  card.className = `slide-card ${data.cls}`;
  card.innerHTML = `<h2 style="margin:0">${data.title}</h2>`;
  cardEls.push(card);
  wrap.appendChild(card);
});
c.appendChild(wrap);

function updateCards() {
  cardEls.forEach((card, i) => {
    let offset = i - currentIndex;
    if (offset === 0) {
      card.style.transform = `translateX(0px) translateZ(0px) rotateY(0deg)`;
      card.style.opacity = '1';
      card.style.zIndex = '10';
    } else if (offset > 0) {
      card.style.transform = `translateX(80px) translateZ(-100px) rotateY(-20deg)`;
      card.style.opacity = '0.6';
      card.style.zIndex = '5';
    } else {
      card.style.transform = `translateX(-80px) translateZ(-100px) rotateY(20deg)`;
      card.style.opacity = '0.6';
      card.style.zIndex = '5';
    }
  });
}
updateCards();

let startX = 0;
wrap.addEventListener('pointerdown', (e) => startX = e.clientX);
wrap.addEventListener('pointerup', (e) => {
  let endX = e.clientX;
  if (startX - endX > 50 && currentIndex < cardsData.length - 1) currentIndex++;
  else if (endX - startX > 50 && currentIndex > 0) currentIndex--;
  updateCards();
});

