const el = document.getElementById('container');
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = el.offsetWidth || 400; canvas.height = el.offsetHeight || 500;
el.appendChild(canvas);

let points = [];
const radius = 100;
const bands = 15;

for (let lat = 0; lat <= bands; lat++) {
  const theta = lat * Math.PI / bands;
  const sinTheta = Math.sin(theta);
  const cosTheta = Math.cos(theta);
  for (let lon = 0; lon <= bands; lon++) {
    const phi = lon * 2 * Math.PI / bands;
    const x = radius * Math.cos(phi) * sinTheta;
    const y = radius * cosTheta;
    const z = radius * Math.sin(phi) * sinTheta;
    points.push({x, y, z});
  }
}

let angleX = 0.01;
let angleY = 0.01;

function draw() {
  ctx.fillStyle = '#02000a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  const cx = canvas.width / 2;
  const cy = canvas.height / 2;

  points.forEach(p => {
    // Rotation Y
    const cosY = Math.cos(angleY), sinY = Math.sin(angleY);
    let x1 = p.x * cosY - p.z * sinY;
    let z1 = p.z * cosY + p.x * sinY;
    // Rotation X
    const cosX = Math.cos(angleX), sinX = Math.sin(angleX);
    let y1 = p.y * cosX - z1 * sinX;
    let z2 = z1 * cosX + p.y * sinX;

    p.x = x1; p.y = y1; p.z = z2;

    const scale = 200 / (200 + p.z);
    const projX = cx + p.x * scale;
    const projY = cy + p.y * scale;

    ctx.beginPath();
    ctx.arc(projX, projY, scale * 1.5, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(0, 255, 204, ${scale})`;
    ctx.shadowBlur = 5; ctx.shadowColor = '#00ffcc';
    ctx.fill();
  });
  requestAnimationFrame(draw);
}
draw();

el.addEventListener('pointermove', (e) => {
  const rect = el.getBoundingClientRect();
  const x = (e.clientX - rect.left) / canvas.width - 0.5;
  const y = (e.clientY - rect.top) / canvas.height - 0.5;
  angleY = x * 0.1;
  angleX = y * 0.1;
});

