const textWrap = document.createElement('div');
textWrap.className = 'gravity-text';
const word = "BOUNCE";
const letters = [];

word.split('').forEach((l) => {
  const span = document.createElement('span');
  span.className = 'g-letter';
  span.innerText = l;
  span.y = 0; span.vy = 0;
  letters.push(span);
  textWrap.appendChild(span);
});
c.appendChild(textWrap);

let isFalling = false;

textWrap.addEventListener('pointerdown', () => {
  if(isFalling) return;
  isFalling = true;
  letters.forEach((span) => {
    span.vy = -(Math.random() * 15 + 10); // Upar no dhakko
  });
});

function animateGravity() {
  if (isFalling) {
    let allSettled = true;
    letters.forEach((span) => {
      span.vy += 0.8; // Gravity
      span.y += span.vy;
      if (span.y > 0) {
        span.y = 0;
        span.vy *= -0.6; // Bounce
        if (Math.abs(span.vy) > 1) allSettled = false;
      } else {
        allSettled = false;
      }
      span.style.transform = `translateY(${span.y}px)`;
    });
    if (allSettled) isFalling = false;
  }
  requestAnimationFrame(animateGravity);
}
animateGravity();

