const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';
const text = document.createElement('div');
text.className = 'liquid-text';
text.innerText = 'MOTIONZYNC';
c.appendChild(text);

const el = document.getElementById('container');
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = el.offsetWidth || 400; canvas.height = el.offsetHeight || 500;
el.appendChild(canvas);

let particles = [];

el.addEventListener('pointermove', (e) => {
  const rect = el.getBoundingClientRect();
  for (let i = 0; i < 3; i++) {
    particles.push({
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      vx: (Math.random() - 0.5) * 4,
      vy: (Math.random() - 0.5) * 4,
      life: 1,
      color: `hsl(${Math.random() * 60 + 280}, 100%, 70%)`
    });
  }
});

function draw() {
  ctx.fillStyle = 'rgba(21, 5, 36, 0.2)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.x += p.vx; p.y += p.vy;
    p.vy += 0.15; // Gravity (ગ્રેવિટી)
    p.life -= 0.02;

    if (p.life <= 0) { particles.splice(i, 1); continue; }

    ctx.beginPath();
    ctx.arc(p.x, p.y, p.life * 4, 0, Math.PI * 2);
    ctx.fillStyle = p.color;
    ctx.shadowBlur = 10; ctx.shadowColor = p.color;
    ctx.fill();
  }
  requestAnimationFrame(draw);
}
draw();

