const el = document.getElementById('container');
const c = document.createElement('canvas');
const ctx = c.getContext('2d');
c.width = el.offsetWidth || 400; c.height = el.offsetHeight || 500;
el.appendChild(c);
const W = c.width, H = c.height;

const dots = Array.from({length: 50}, () => ({
  x: Math.random() * W, y: Math.random() * H,
  vx: (Math.random() - 0.5) * 1.5, vy: (Math.random() - 0.5) * 1.5,
  r: Math.random() * 2 + 1
}));

function draw() {
  ctx.fillStyle = 'rgba(5, 5, 15, 0.3)'; ctx.fillRect(0, 0, W, H);
  dots.forEach(d => {
    d.x += d.vx; d.y += d.vy;
    if (d.x < 0 || d.x > W) d.vx *= -1;
    if (d.y < 0 || d.y > H) d.vy *= -1;
    ctx.beginPath(); ctx.arc(d.x, d.y, d.r, 0, Math.PI * 2);
    ctx.fillStyle = '#00d2ff'; ctx.shadowBlur = 10; ctx.shadowColor = '#00d2ff'; ctx.fill();
  });

  for (let i = 0; i < dots.length; i++) {
    for (let j = i + 1; j < dots.length; j++) {
      const dist = Math.hypot(dots[i].x - dots[j].x, dots[i].y - dots[j].y);
      if (dist < 80) {
        ctx.beginPath(); ctx.moveTo(dots[i].x, dots[i].y); ctx.lineTo(dots[j].x, dots[j].y);
        ctx.strokeStyle = `rgba(0, 210, 255, ${1 - dist/80})`; ctx.lineWidth = 1; ctx.stroke();
      }
    }
  }
  requestAnimationFrame(draw);
}
draw();

