const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;perspective:1000px;background:transparent;';

const card = document.createElement('div');
card.className = 'credit-card';

const chip = document.createElement('div');
chip.className = 'card-chip';

const num = document.createElement('div');
num.className = 'card-number';
num.innerText = '**** **** **** 4040';

card.appendChild(chip);
card.appendChild(num);
c.appendChild(card);

let isDragging = false;
let startX, startY, rotX = 0, rotY = 0;

card.addEventListener('pointerdown', (e) => {
  isDragging = true; startX = e.clientX; startY = e.clientY;
});
document.addEventListener('pointermove', (e) => {
  if (!isDragging) return;
  const deltaX = e.clientX - startX; const deltaY = e.clientY - startY;
  rotY += deltaX * 0.5; rotX -= deltaY * 0.5;
  card.style.transform = `rotateX(${rotX}deg) rotateY(${rotY}deg)`;
  startX = e.clientX; startY = e.clientY;
});
document.addEventListener('pointerup', () => {
  if (isDragging) {
    isDragging = false;
    card.style.transition = 'transform 0.5s ease';
    card.style.transform = 'rotateX(0deg) rotateY(0deg)';
    rotX = 0; rotY = 0;
    setTimeout(() => card.style.transition = 'transform 0.1s', 500);
  }
});

