(function initQuantumAnimation() {
  // Canvas Setup
  let canvas = document.getElementById('quantum-canvas');
  if (!canvas) {
    canvas = document.createElement('canvas');
    canvas.id = 'quantum-canvas';
    document.body.appendChild(canvas);
  }

  // DOM Elements Injection (For Live Preview)
  if (!document.querySelector('.quantum-core')) {
    const core = document.createElement('div');
    core.className = 'quantum-core';

    const ring1 = document.createElement('div');
    ring1.className = 'orbital-ring';

    const ring2 = document.createElement('div');
    ring2.className = 'orbital-ring-outer';

    document.body.appendChild(core);
    document.body.appendChild(ring1);
    document.body.appendChild(ring2);
  }

  const ctx = canvas.getContext('2d');
  let width, height;
  let particles = [];
  const particleCount = 40;

  function resize() {
    width = canvas.width = window.innerWidth;
    height = canvas.height = window.innerHeight;
  }
  window.addEventListener('resize', resize);
  resize();

  class QuantumParticle {
    constructor() {
      this.reset();
    }

    reset() {
      this.radius = Math.random() * 140 + 40;
      this.angle = Math.random() * Math.PI * 2;
      this.speed = (Math.random() * 0.015 + 0.005) * (Math.random() > 0.5 ? 1 : -1);
      this.size = Math.random() * 2 + 1;
      this.color = Math.random() > 0.5 ? '#00f2fe' : '#ec4899';
      this.alpha = Math.random() * 0.6 + 0.2;
    }

    update() {
      this.angle += this.speed;
      this.x = width / 2 + Math.cos(this.angle) * this.radius;
      this.y = height / 2 + Math.sin(this.angle) * (this.radius * 0.6);
    }

    draw() {
      ctx.save();
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
      ctx.fillStyle = this.color;
      ctx.shadowColor = this.color;
      ctx.shadowBlur = 10;
      ctx.globalAlpha = this.alpha;
      ctx.fill();
      ctx.restore();
    }
  }

  for (let i = 0; i < particleCount; i++) {
    particles.push(new QuantumParticle());
  }

  function renderLoop() {
    ctx.fillStyle = 'rgba(6, 8, 19, 0.25)';
    ctx.fillRect(0, 0, width, height);

    for (let i = 0; i < particles.length; i++) {
      particles[i].update();
      particles[i].draw();

      for (let j = i + 1; j < particles.length; j++) {
        const dx = particles[i].x - particles[j].x;
        const dy = particles[i].y - particles[j].y;
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < 70) {
          ctx.strokeStyle = particles[i].color;
          ctx.globalAlpha = (1 - distance / 70) * 0.2;
          ctx.lineWidth = 0.8;
          ctx.beginPath();
          ctx.moveTo(particles[i].x, particles[i].y);
          ctx.lineTo(particles[j].x, particles[j].y);
          ctx.stroke();
        }
      }
    }
    requestAnimationFrame(renderLoop);
  }

  renderLoop();
})();
